update pages set contenu = '{"gabarit":"fiche","chapeau":"SOPREMA est un acteur mondial de l''étanchéité et de l''isolation. Son développement industriel génère des chantiers ponctuels qui ne rentrent pas dans le plan de charge des équipes internes.\nMigen y est intervenu en 2025 sur plusieurs missions ciblées, avec des techniciens qualifiés mobilisés à la mission.","fiche":[],"contexte":"**Un transfert de machine mal préparé coûte plus cher que la machine elle-même.** Trois types de situations revenaient chez SOPREMA.\n**Montage mécanique ou électromécanique** de lignes ou de sous-ensembles.\n**Déplacement ou reconfiguration** de machines industrielles.\n**Interventions urgentes** sur chantiers complexes ou en surcharge d''activité.\nAucune de ces trois ne justifie un recrutement. Toutes exigent pourtant une compétence de montage réelle, disponible au moment où le chantier démarre, pas trois mois après.\nCes chantiers ont un point commun : ils tombent en plus du plan de charge. L''équipe maintenance les absorbe, et le préventif du site en paie le prix.\nUn transfert de machine mobilise aussi des compétences que la maintenance courante n''entretient pas. Levage, calage, réalignement, remise en service : ce sont des gestes de montage, pas de dépannage.","intervention":"**Vous mobilisez des techniciens qualifiés selon le besoin**, sans réorganiser vos équipes internes.\n**Vous définissez le périmètre technique à l''avance.** Montage, démontage, transfert de machines, assistance à la production : ce qui est couvert est écrit.\n**Vous gardez l''encadrement chez nous.** Migen assure l''encadrement opérationnel des interventions, pour l''efficacité comme pour la sécurité.\n**Vous savez ce que vous payez.** La facturation se fait à la journée ou au forfait, avec une logistique allégée.\n**Vous mobilisez partout en France**, sur des sites différents, avec la même approche.","resultats":[]}'::jsonb where path = '/preuves/soprema/';
update pages set contenu = jsonb_set(contenu, '{fiche}', (contenu->'fiche') || '[{"libelle":"Client","valeur":"SOPREMA, étanchéité et isolation"},{"libelle":"Périmètre","valeur":"Montage de lignes et sous-ensembles, transfert de machines, renfort de chantier"},{"libelle":"Effectif Migen","valeur":"Équipes mobilisées à la mission"},{"libelle":"Domaines","valeur":"Mécanique, électromécanique, électricité, montage"},{"libelle":"Modalité","valeur":"Facturation à la journée ou au forfait"},{"libelle":"Depuis quand","valeur":"2025"}]'::jsonb) where path = '/preuves/soprema/';
update pages set contenu = jsonb_set(contenu, '{resultats}', (contenu->'resultats') || '[{"valeur":"Les délais de chantier ont été respectés","libelle":"sans pénalité."},{"valeur":"Les transferts de machines ont été sécurisés.","libelle":""},{"valeur":"Le soutien technique a été apporté","libelle":"sans surcharge pour les équipes RH."},{"valeur":"Les charges temporaires ont été absorbées","libelle":"sans recrutement ni réorganisation interne."}]'::jsonb) where path = '/preuves/soprema/';
